"""Candidate on the lean quantile model with occasion timing (D135). Nothing submitted is changed.
(1) writes eda/20b_quantiles_lean.py = eda/20 with BASE/FULL reduced to the lean set (no lifecycle, channel-mix, discount or occasion-flag
    features; D134) plus the three occasion-timing features (D112), merged from data/context_feats.parquet (which has June 2026 rows);
    its backtest is data/q_backtest_lean.parquet (eda/103 leanocct plus the stored point-model column);
(2) runs eda/80 (rules + quantile + NN re-centring of the production chain eda/22 -> 32 -> 41) with eda/22 pointed at the lean module and
    the lean backtest, outputs data/cand_rlo_*;
(3) applies the D121 monthly split (rules + NN profile, no own-shape mix, no July calibration) -> data/cand_rlos_final_forecast_q3.csv."""
import sys, subprocess
sys.stdout.reconfigure(encoding="utf-8")
s20 = open("eda/20_quantiles.py", encoding="utf-8").read()
a = 'def fit_q(tr, te):'
lean = ('# --- lean set + occasion timing (D134/D135) ---\n'
        '_DROP = lambda c: c in ("age_m", "days_live", "color_num", "sh_ret", "sh_drop", "sh_tt", "disc_item", "disc_rel") or c.startswith("occ_")\n'
        'BASE = [c for c in BASE if not _DROP(c)]; FULL = [c for c in FULL if not _DROP(c)]\n'
        '_CF = pd.read_parquet("data/context_feats.parquet")[["origin", "style_color", "occ_next", "occ_last", "occ_n4"]]\n'
        'T1 = T1.merge(_CF, on=["origin", "style_color"], how="left"); BASE += ["occ_next", "occ_last", "occ_n4"]; FULL += ["occ_next", "occ_last", "occ_n4"]\n\n')
assert s20.count(a) == 1
s20 = s20.replace(a, lean + a).replace('Q.to_parquet("data/q_backtest.parquet")', 'Q.to_parquet("data/q_backtest_lean_rerun.parquet")')
s20 = '"""GENERATED by eda/129_candidate_lean.py: eda/20 with the lean feature set + occasion timing (D135). Do not edit by hand."""\n' + s20
open("eda/20b_quantiles_lean.py", "w", encoding="utf-8").write(s20)
s80 = open("eda/80_candidate_rules.py", encoding="utf-8").read()
a1 = 's = open("eda/65_candidate_nn.py", encoding="utf-8").read()'
b1 = (a1 + '\ns = s.replace(\'src22 = open("eda/22_quantile_final.py", encoding="utf-8").read()\', '
      '\'src22 = open("eda/22_quantile_final.py", encoding="utf-8").read().replace("eda/20_quantiles.py", "eda/20b_quantiles_lean.py")'
      '.replace(\\\'pd.read_parquet("data/q_backtest.parquet")\\\', \\\'pd.read_parquet("data/q_backtest_lean.parquet")\\\')\')\n'
      'assert "20b_quantiles_lean" in s')
assert s80.count(a1) == 1
s80 = s80.replace(a1, b1).replace('s = s.replace("cand_nn_", "cand_rnn_")', 's = s.replace("cand_nn_", "cand_rlo_")')
assert 'cand_rlo_' in s80
open("eda/129b_run_lean_chain.py", "w", encoding="utf-8").write('"""GENERATED by eda/129_candidate_lean.py: eda/80 pointed at the lean quantile model (D135)."""\n' + s80)
r = subprocess.run([sys.executable, "eda/129b_run_lean_chain.py"], capture_output=True, text=True, encoding="utf-8"); print(r.stdout[-3000:], r.stderr[-2000:])
s106 = open("eda/106_candidate_shape.py", encoding="utf-8").read().replace("cand_rnn_final_forecast_q.csv", "cand_rlo_final_forecast_q.csv").replace("cand_rnns_final_forecast_q3.csv", "cand_rlos_final_forecast_q3.csv")
s106 = s106.replace('("candidate rules+q+NN (old split + July calibration)", P)', '("lean candidate (old split + July calibration)", pd.read_csv("data/cand_rlo_final_forecast_q4.csv", index_col=0)), ("rules+q+NN candidate (D105)", P)').replace('("candidate rules+q+NN, rules + NN split", C)', '("lean candidate, rules + NN split", C)')
open("eda/129c_lean_shape.py", "w", encoding="utf-8").write('"""GENERATED by eda/129_candidate_lean.py: eda/106 on the lean candidate (D135)."""\n' + s106)
r = subprocess.run([sys.executable, "eda/129c_lean_shape.py"], capture_output=True, text=True, encoding="utf-8"); print(r.stdout[-2500:], r.stderr[-1500:])
